// 特殊能力を多用する魔物 (abRate がこれ以上) は、図鑑の札に「多用」と添える
export const AB_RATE_HEAVY = 0.4;

// モンスター定義から特徴キーの並びを導く (重複なし、表示順は定義順)。
// 既存の ability / role と新フィールドを単一の語彙へ正規化する。
// 宙に浮く魔物か (戦闘待機中・図鑑で上下にゆらめかせるのはこれだけ。地に足の着いた者は揺らさない)
// 種族で決まるもの: 飛獣/鳥人/幽鬼/精霊。それ以外の種族でもはねや翼で飛ぶ個体は ID で個別に指定する。
const FLOAT_RACES = new Set(["wing", "avian", "specter", "elemental"]);
const FLOAT_IDS = new Set([
  "bat", "wraith", "cm_bat", "d02_imp", "d03_ghost",
  "bs_bloatfly", "bs_giantmoth", "bs_emberswarm", "bs_blightmoth", "bs_windscythe", "bs_sparkswarm", "bs_emberfly", "bs_lightmoth",
  "bs_familiarswarm", "bs_fallenangel", "bs_cyclonedjinn", "bs_abyssjelly",
  "bs_wyvern", "bs_stormwyvern", "bs_wyvernlord", "bs_skydrake", "bs_wingedterror",
]);
// 幽鬼に分類されていても生身の者 (浮かない)
const GROUNDED_IDS = new Set(["bs_cultist", "bs_stonegorgon", "el_cinderking", "bs_icewraith", "bs_glaciallord"]); // 残り火の王は燃えさしの山から立ちのぼる。氷霊は腰まで氷柱に埋まり、凍王は氷の玉座に座る
export function isFloating(m, key) {
  if (!m) return false;
  const id = key || m.key || m.id || "";
  if (GROUNDED_IDS.has(id)) return false;
  return FLOAT_IDS.has(id) || FLOAT_RACES.has(m.race);
}

export function monsterTraitKeys(m) {
  if (!m) return [];
  const keys = [];
  const add = (k) => { if (k && TRAITS[k] && !keys.includes(k)) keys.push(k); };
  if (m.metal) { add("metal"); add("fleet"); add("evasive"); }
  if (m.haste) add("haste");
  if (m.swift) add("swift");
  if (m.evasive) add("evasive");
  if (m.physResist) add("physResist");
  if (m.magWeak) add("magWeak");
  if (m.regen) add("regen");
  if (m.pack) add("pack");
  if (m.magResist) add("magResist");
  if (m.enrage) add("enrage");
  if (m.endure) add("endure");
  if (m.lifesteal) add("lifesteal");
  if (m.multistrike) add("multistrike");
  if (m.barrier) add("barrier");
  if (m.role === "summoner") add("summon");
  if (m.role === "healer") add("heal");
  if (m.role === "guard") add("guard");
  add(m.ability); // poison/paralyze/stone/drain/soulSteal/goldSteal/critical/breath/spell/warcry/weaken/sleep/charm/confuse/charge/sunder/dispel
  // 主・精鋭は誰でも大技を溜め (combat.js の予兆)、深い弱体を払いのける
  if ((m.boss || m.elite) && !m.metal) { add("charge"); add("shake"); }
  for (const t of m.traits || []) add(t);
  return keys;
}

// 表示用に {key,label,desc} の配列へ展開する
// 物理・魔法は抵抗値と軽減率を表示する
export function monsterTraits(m) {
  return monsterTraitKeys(m).map((k) => {
    if (["physResist", "magResist"].includes(k) && m[k]) {
      const r = m[k];
      return { key: k, label: `${k === "physResist" ? "物理" : "魔法"}抵抗値 ${r}`, desc: r === 100 ? "無効" : `${r}%軽減` };
    }
    // 特殊能力を多用する個体: 札に「多用」を添える
    if (k === m.ability && m.abRate >= AB_RATE_HEAVY) return { key: k, label: `${TRAITS[k].label}・多用`, desc: `${TRAITS[k].desc} (頻繁に使う)` };
    return { key: k, ...TRAITS[k] };
  });
}

// 定義の配列を { id: monster } に変換 (重複IDは即エラー)
export function defMonsters(defs) {
  const out = {};
  for (const d of defs) {
    const m = defMonster(d);
    if (out[m.id]) throw new Error("duplicate monster id: " + m.id);
    out[m.id] = m;
  }
  return out;
}
